CREATE OR REPLACE VIEW `rs_requested` AS select count(`od`.`product_id`) AS `requested`,`od`.`product_id` AS `product_id`,`p`.`name` AS `name`,sum(`od`.`qty`) AS `qty`,`o`.`company_id` AS `company_id`,`o`.`customer_id` AS `customer_id` from ((`orders` `o` join `order_details` `od` on(`o`.`order_id` = `od`.`order_id`)) join `products` `p` on(`od`.`product_id` = `p`.`pro_id`)) where `o`.`status_id` = 14 group by `od`.`product_id`,`o`.`company_id`,`o`.`customer_id`,`p`.`name` order by `o`.`company_id`,`o`.`customer_id`;
